-- Init script for the sftp:// service (loaded by test/configs/sftp.json).
-- OpenDAL's sftp service authenticates with a key only (no password) and shells
-- out to the system `ssh`; the throwaway keypair is generated by `make sftp-up`.
-- `accept` skips host-key verification against the ephemeral container.
CREATE SECRET sftp_common (
    TYPE sftp, SCOPE 'sftp://',
    config MAP{
        'endpoint': '${OPENDAL_SFTP_ENDPOINT}',
        'user': '${OPENDAL_SFTP_USER}',
        'key': '${OPENDAL_SFTP_KEY}',
        'root': '${OPENDAL_SFTP_ROOT}',
        'known_hosts_strategy': 'accept'
    }
);
